#include "ILI9488.h"
#include <string.h>
#include <stdio.h>

static ILI9488_DMA_State dma_state = ILI9488_DMA_IDLE;
static ILI9488_DMATxCpltCallback dma_callback = NULL;
static volatile uint8_t dma_complete_flag = 0;
static ILI9488_Rotation lcd_rotation = ILI9488_ROTATION_0;

static void LCD_Color565To666(uint16_t color, uint8_t *rgb){
	rgb[0] = ((color >> 11) & 0x1F) << 3;
	rgb[1] = ((color >> 5) & 0x3F) << 2;
	rgb[2] = (color & 0x1F) << 3;
}

uint16_t LCD_GetWidth(void){
    return (lcd_rotation == ILI9488_ROTATION_90 || lcd_rotation == ILI9488_ROTATION_270) ? LCD_HEIGHT : LCD_WIDTH;
}

uint16_t LCD_GetHeight(void){
    return (lcd_rotation == ILI9488_ROTATION_90 || lcd_rotation == ILI9488_ROTATION_270) ? LCD_WIDTH : LCD_HEIGHT;
}

/* ── 硬件 SPI1 传输 ── */
extern SPI_HandleTypeDef hspi1;
static inline void SPI1_Tx(uint8_t data) { HAL_SPI_Transmit(&hspi1, &data, 1, 10); }
static inline void SPI1_TxBuf(const uint8_t *data, uint32_t len) { HAL_SPI_Transmit(&hspi1, (uint8_t *)data, (uint16_t)len, 5000); }

void LCD_WriteCommand(uint8_t command){ DC_LOW(); CS_LOW(); SPI1_Tx(command); CS_HIGH(); }
void LCD_WriteData(uint8_t data){ DC_HIGH(); CS_LOW(); SPI1_Tx(data); CS_HIGH(); }
void LCD_WriteData16(uint16_t data){ uint8_t rgb[3]; LCD_Color565To666(data, rgb); DC_HIGH(); CS_LOW(); SPI1_TxBuf(rgb, 3); CS_HIGH(); }
void LCD_WriteDataBuffer16(const uint16_t* buffer, uint32_t len){
    if (len == 0) return;
    DC_HIGH(); CS_LOW();
    for (uint32_t i = 0; i < len; i++) { uint8_t rgb[3]; LCD_Color565To666(buffer[i], rgb); SPI1_TxBuf(rgb, 3); }
    CS_HIGH();
}

void HAL_SPI_TxCpltCallback(SPI_HandleTypeDef *hspi){
    if (hspi->Instance == SPI1) { dma_complete_flag = 1; dma_state = ILI9488_DMA_IDLE; if (dma_callback != NULL) dma_callback(); }
}
void LCD_WaitDMAComplete(void){ uint32_t start_time = HAL_GetTick(); while(dma_complete_flag == 0){ if(HAL_GetTick() - start_time > 2000){ dma_state = ILI9488_DMA_ERROR; break; } } }
ILI9488_DMA_State ILI9488_GetDMAState(void) { return dma_state; }
void ILI9488_SetDMAState(ILI9488_DMA_State state) { dma_state = state; }
void ILI9488_SetDMACallback(ILI9488_DMATxCpltCallback callback) { dma_callback = callback; }

void LCD_SetRotation(ILI9488_Rotation rotation) {
    uint8_t madctl;
    switch (rotation) {
        case ILI9488_ROTATION_0:   madctl = 0x48; break;
        case ILI9488_ROTATION_90:  madctl = 0x28; break;
        case ILI9488_ROTATION_180: madctl = 0x88; break;
        case ILI9488_ROTATION_270: madctl = 0x68; break;
        default:                   madctl = 0x48; rotation = ILI9488_ROTATION_0; break;
    }
    LCD_WriteCommand(0x36); LCD_WriteData(madctl);
    lcd_rotation = rotation;
}

void LCD_Reset(void) { RST_HIGH(); HAL_Delay(5); RST_LOW();  HAL_Delay(20); RST_HIGH(); HAL_Delay(20); }

void LCD_Init(void){
    LCD_Reset();
    LCD_WriteCommand(0x01); HAL_Delay(10);
    LCD_WriteCommand(0xE0); uint8_t gammaP[] = {0x00,0x03,0x09,0x08,0x16,0x0A,0x3F,0x78,0x4C,0x09,0x0A,0x08,0x16,0x1A,0x0F}; for(uint8_t i=0;i<15;i++) LCD_WriteData(gammaP[i]);
    LCD_WriteCommand(0xE1); uint8_t gammaN[] = {0x00,0x16,0x19,0x03,0x0F,0x05,0x32,0x45,0x46,0x04,0x0E,0x0D,0x35,0x37,0x0F}; for(uint8_t i=0;i<15;i++) LCD_WriteData(gammaN[i]);
    LCD_WriteCommand(0xC0); LCD_WriteData(0x17); LCD_WriteData(0x15);
    LCD_WriteCommand(0xC1); LCD_WriteData(0x41);
    LCD_WriteCommand(0xC5); LCD_WriteData(0x00); LCD_WriteData(0x12); LCD_WriteData(0x80);
    LCD_SetRotation(ILI9488_ROTATION_270);
    LCD_WriteCommand(0x3A); LCD_WriteData(0x66);
    LCD_WriteCommand(0xB0); LCD_WriteData(0x00);
    LCD_WriteCommand(0xB1); LCD_WriteData(0xA0);
    LCD_WriteCommand(0xB4); LCD_WriteData(0x02);
    LCD_WriteCommand(0xB6); LCD_WriteData(0x02); LCD_WriteData(0x02);
    LCD_WriteCommand(0xE9); LCD_WriteData(0x00);
    LCD_WriteCommand(0xF7); LCD_WriteData(0xA9); LCD_WriteData(0x51); LCD_WriteData(0x2C); LCD_WriteData(0x82);
    LCD_WriteCommand(0x11); HAL_Delay(120);
    LCD_WriteCommand(0x29); HAL_Delay(20);
    LCD_FillColor(LCD_BLACK);
}
void LCD_SPI_Init(void) { /* HW SPI1 done by MX_SPI1_Init */ }
uint16_t LCD_ReadID(void) { return 0x9488; }

void LCD_SetWindow(uint16_t x0, uint16_t y0, uint16_t x1, uint16_t y1) {
    LCD_WriteCommand(0x2A); LCD_WriteData(x0 >> 8); LCD_WriteData(x0 & 0xFF); LCD_WriteData(x1 >> 8); LCD_WriteData(x1 & 0xFF);
    LCD_WriteCommand(0x2B); LCD_WriteData(y0 >> 8); LCD_WriteData(y0 & 0xFF); LCD_WriteData(y1 >> 8); LCD_WriteData(y1 & 0xFF);
}

void LCD_DrawPixel(uint16_t x, uint16_t y, uint16_t color) {
    uint16_t w = LCD_GetWidth(), h = LCD_GetHeight();
    if (x >= w || y >= h) return;
    LCD_SetWindow(x, y, x, y); LCD_WriteCommand(0x2C);
    uint8_t rgb[3]; LCD_Color565To666(color, rgb);
    DC_HIGH(); CS_LOW(); SPI1_TxBuf(rgb, 3); CS_HIGH();
}

void LCD_FillColor(uint16_t color) {
    uint16_t w = LCD_GetWidth(), h = LCD_GetHeight();
    uint32_t total = (uint32_t)w * h;
    LCD_SetWindow(0, 0, w-1, h-1); LCD_WriteCommand(0x2C);
    uint8_t rgb[3]; LCD_Color565To666(color, rgb);
    uint8_t chunk[600]; for (uint32_t i=0; i<600; i+=3) { chunk[i]=rgb[0]; chunk[i+1]=rgb[1]; chunk[i+2]=rgb[2]; }
    DC_HIGH(); CS_LOW();
    uint32_t remain = total;
    while (remain > 0) { uint32_t pix = (remain > 200) ? 200 : remain; SPI1_TxBuf(chunk, pix*3); remain -= pix; }
    CS_HIGH();
}

void LCD_FillRect(uint16_t x1, uint16_t y1, uint16_t x2, uint16_t y2, uint16_t color) {
    if (x1>x2){uint16_t t=x1;x1=x2;x2=t;} if (y1>y2){uint16_t t=y1;y1=y2;y2=t;}
    uint16_t w=LCD_GetWidth(),h=LCD_GetHeight(); if (x1>=w||y1>=h) return; if (x2>=w) x2=w-1; if (y2>=h) y2=h-1;
    uint32_t total = (uint32_t)(x2-x1+1)*(uint32_t)(y2-y1+1);
    LCD_SetWindow(x1,y1,x2,y2); LCD_WriteCommand(0x2C);
    uint8_t rgb[3]; LCD_Color565To666(color, rgb);
    uint8_t chunk[600]; for (uint32_t i=0; i<600; i+=3) { chunk[i]=rgb[0]; chunk[i+1]=rgb[1]; chunk[i+2]=rgb[2]; }
    DC_HIGH(); CS_LOW();
    uint32_t remain=total;
    while(remain>0){uint32_t pix=(remain>200)?200:remain; SPI1_TxBuf(chunk,pix*3); remain-=pix;}
    CS_HIGH();
}

