void LCD_DrawChar(uint16_t x, uint16_t y, char c, uint16_t color, uint16_t bg) {
    if (c < 32 || c > 126) c = ' ';
    uint8_t idx = (uint8_t)(c - 32); const uint8_t *ch = font6x8[idx];
    uint16_t w = LCD_GetWidth(), h = LCD_GetHeight();
    if (x + 5 >= w || y + 7 >= h) return;
    uint8_t rgb_fg[3], rgb_bg[3];
    LCD_Color565To666(color, rgb_fg); LCD_Color565To666(bg, rgb_bg);
    LCD_SetWindow(x, y, x + 5, y + 7); LCD_WriteCommand(0x2C);
    DC_HIGH(); CS_LOW();
    for (int8_t row = 0; row < 8; row++) {
        for (int8_t col = 0; col < 6; col++) {
            uint8_t bit = (ch[col] >> (7 - row)) & 1;
            uint8_t *rgb = bit ? rgb_fg : rgb_bg;
            SPI1_TxBuf(rgb, 3);
        }
    }
    CS_HIGH();
}

void LCD_DrawString(uint16_t x, uint16_t y, const char *str, uint16_t color, uint16_t bg) {
    if (!str) return;
    uint16_t len = 0; const char *p = str; while (*p++) len++;
    uint16_t total_w = len * 7;
    uint16_t sw = LCD_GetWidth(), sh = LCD_GetHeight();
    if (x + total_w > sw) total_w = sw - x;
    if (y + 8 > sh || total_w == 0) return;
    LCD_FillRect(x, y, x + total_w - 1, y + 7, bg);
    uint8_t rgb_fg[3], rgb_bg[3];
    LCD_Color565To666(color, rgb_fg); LCD_Color565To666(bg, rgb_bg);
    LCD_SetWindow(x, y, x + total_w - 1, y + 7); LCD_WriteCommand(0x2C);
    DC_HIGH(); CS_LOW();
    for (int8_t row = 0; row < 8; row++) {
        for (int16_t ci = 0; ci < len; ci++) {
            char chc = str[ci]; if (chc < 32 || chc > 126) chc = ' ';
            const uint8_t *fc = font6x8[(uint8_t)(chc - 32)];
            SPI1_TxBuf(rgb_bg, 3);
            for (int8_t col = 0; col < 6; col++) {
                uint8_t bit = (fc[col] >> (7 - row)) & 1;
                uint8_t *rgb = bit ? rgb_fg : rgb_bg;
                SPI1_TxBuf(rgb, 3);
            }
        }
    }
    CS_HIGH();
}